#!/usr/bin/env python3
"""Tutorials TU1 — the guide's tutorials checked against the app (spec §11
TU-2). A line of `make test`; no app instance, no media, no key.

    python3 tools/proof/tutorial_check.py                    # the guide (make test)
    python3 tools/proof/tutorial_check.py --facts FILE       # against saved facts, no build
    python3 tools/proof/tutorial_check.py --save-facts FILE  # also write the probe's facts
    python3 tools/proof/tutorial_check.py --selftest         # CONTROL + 14 mutants

Every page of `docs/guide/` is parsed by `tools/tutorials/tutorial_extract.py`
(the build step's own parser: structure, JSON, ids unique), then each tutorial
is checked against TU-2's closed vocabulary and the app's facts, which
`tutorial_probe.swift` prints — compiled over `app/Sources` with
`-D FRAMEJOB_DEV_TOOLS` through `swift_build.py`'s `build()`, reused when every
input is byte-identical: the prepared catalog (a `show_me` tool, its argument
keys, an `enum` value), the dev tools' names (refused), the target table
(`TutorialTargets.manifest()`: spotlights, a `reveal`'s tab, sub-tab, section
and home), the built menu bar (a sentence's bold `A ▸ B` and a menu Show Me,
whose leaf's selector must be a key of `capture_spike/inventory.json`'s
`selectors`) and a fixture project's clips (a `changed` path and a patch's
leaves). The table's section ids are also compared, both ways, with the
`id: "<x>", title:` literals in `app/Sources`.

Prints `FAIL <page>[ tutorial <id>][ step <n>]: <message>` per problem, then
`tutorial_check: <T> tutorials, <S> steps, <P> problems`; exit 0 iff P is 0.
A probe that does not build or answer is a scored FAIL (exit 1), never a skip.

`--selftest` copies `tutorial_fixtures/` (a page using every vocabulary key,
the facts in miniature, an inventory, a sources folder) into
`work/tutorial_check/<case>/` and requires CONTROL to show 0 problems, then
each of the 14 mutants (`MUTANTS`, one per refusal class) exactly one problem,
naming its page, tutorial and step. No build.
"""

import argparse
import json
import re
import shutil
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
sys.path.insert(0, str(HERE))
sys.path.insert(0, str(HERE / "graphics_spike"))
sys.path.insert(0, str(ROOT / "tools" / "tutorials"))
import bounded  # noqa: E402
import swift_build  # noqa: E402
from tutorial_extract import Problem, parse_guide  # noqa: E402

GUIDE = ROOT / "docs" / "guide"
INVENTORY = HERE / "capture_spike" / "inventory.json"
SOURCES = ROOT / "app" / "Sources"
FIXTURES = HERE / "tutorial_fixtures"
WORK = HERE / "work" / "tutorial_check"
PROBE_SWIFT = HERE / "tutorial_probe.swift"
WALL_BUILD, WALL_RUN = 900, 300
TABLE_PAGE = "TutorialTargets.swift"

KINDS = ("media", "still", "image", "text", "shape", "graphic", "nest", "adjustment")
FILTER_KEYS = ("has_sound", "has_pixels", "kind", "follows_clip", "has_transition")
STEP_KEYS = ("reveal", "spotlight", "wait", "show_me", "optional")
WAIT_KEYS = ("selection", "changed", "clips", "playhead", "range", "sheet", "export_started",
             "playing")
REFS = ("$selection", "$created")
PLAIN_VARIABLES = ("$selection", "$created", "$playhead")
PATCH_GROUPS = {"set_video": "video", "set_audio": "audio", "set_text": "text",
                "set_shape": "shape"}
LITERAL = re.compile(r'id: "([^"]+)", title:')
BOLD = re.compile(r"\*\*(.+?)\*\*")
ARROW = "▸"


class ProbeFailed(RuntimeError):
    pass


# ---------------------------------------------------------------------------
# The probe.


def build_facts() -> dict:
    """The probe's answer; raises ProbeFailed when it does not build or answer."""
    probe_dir = WORK / "probe"
    probe_dir.mkdir(parents=True, exist_ok=True)
    entry = probe_dir / "main.swift"
    source = PROBE_SWIFT.read_text(encoding="utf-8")
    if not entry.exists() or entry.read_text(encoding="utf-8") != source:
        entry.write_text(source, encoding="utf-8")
    binary = probe_dir / "tutorial_probe"
    sources = swift_build.app_sources()
    print(f"probe: {len(sources)} sources through swift_build (up to {WALL_BUILD} s)…",
          flush=True)
    try:
        built = swift_build.build(sources=sources + [entry], output=binary,
                                  defines=["FRAMEJOB_DEV_TOOLS"], timeout=WALL_BUILD)
    except swift_build.SwiftBuildFailed as error:
        raise ProbeFailed(f"the probe did not build: swiftc "
                          f"{error.rc if error.rc is not None else 'before running'} "
                          f"(expired {error.expired}): "
                          + " | ".join(error.diagnostics[:6] or ["(no output)"])) from None
    print("probe: up to date" if built.reused else f"probe: built in {built.seconds:.0f} s",
          flush=True)
    runs = WORK / "runs"
    shutil.rmtree(runs, ignore_errors=True)
    runs.mkdir(parents=True)
    ran = bounded.run([str(binary), str(runs)], WALL_RUN, cwd=str(probe_dir),
                      env=bounded.child_env())
    if ran["expired"]:
        raise ProbeFailed(f"the probe ran past {WALL_RUN} s and was killed")
    for line in ran["stdout"].splitlines():
        if line.startswith("ANSWER "):
            facts = json.loads(line[len("ANSWER "):])
            if "error" in facts:
                raise ProbeFailed(f"the probe answered an error: {facts['error']}")
            return facts
    raise ProbeFailed(f"the probe printed no answer (exit {ran['rc']}): "
                      f"{ran['stderr'].strip()[-400:]}")


# ---------------------------------------------------------------------------
# The vocabulary.


def _int(value) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _resolves(clips, path: str) -> bool:
    """Whether the dotted clip-JSON path names a key in any fixture clip."""
    for clip in clips:
        here, found = clip, True
        for part in path.split("."):
            if isinstance(here, dict) and part in here:
                here = here[part]
            else:
                found = False
                break
        if found:
            return True
    return False


def _filter(value, where, extra=()):
    """Problems of a clip filter (TU-2 (3)), with `extra` keys also allowed."""
    if not isinstance(value, dict):
        return [f"{where} is not an object"]
    out = []
    for key, item in value.items():
        if key in extra:
            continue
        if key not in FILTER_KEYS:
            out.append(f"{where} has an unknown key {key!r}")
        elif key == "kind":
            if item not in KINDS:
                out.append(f"{where}'s kind {item!r} is not one of {', '.join(KINDS)}")
        elif not isinstance(item, bool):
            out.append(f"{where}'s {key} is not a boolean")
    return out


def _reference(value, where):
    if value in REFS:
        return []
    if isinstance(value, dict) and len(value) == 1 and ("$pick" in value or "$first" in value):
        return _variable(value, where)
    return [f"{where}: {json.dumps(value, ensure_ascii=False)} is not $selection, $created, "
            "a $pick or a $first"]


def _variable(value, where):
    """Problems of a `$`-keyed object (TU-2 (9))."""
    if len(value) != 1:
        return [f"{where}: a variable object holds one key, not {sorted(value)}"]
    (key, item), = value.items()
    if key == "$pick":
        return _filter(item, f"{where} $pick")
    if key == "$first":
        return [] if item in REFS else [f"{where}: $first takes $selection or $created, "
                                        f"not {item!r}"]
    if key == "$track":
        return [] if item == "front" else [f"{where}: $track takes \"front\", not {item!r}"]
    if key == "$time":
        if not isinstance(item, dict) or set(item) != {"of", "at"}:
            return [f"{where}: $time takes exactly {{of, at}}"]
        out = _reference(item["of"], f"{where} $time.of")
        if item["at"] not in ("start", "middle", "end"):
            out.append(f"{where}: $time.at {item['at']!r} is not start, middle or end")
        return out
    return [f"{where}: unknown variable {key!r}"]


def _variables(value, where):
    """Every variable problem at any depth of a Show Me argument."""
    if isinstance(value, str):
        if value.startswith("$") and value not in PLAIN_VARIABLES:
            return [f"{where}: unknown variable {value!r}"]
        return []
    if isinstance(value, list):
        return [p for index, item in enumerate(value)
                for p in _variables(item, f"{where}[{index}]")]
    if isinstance(value, dict):
        if any(isinstance(key, str) and key.startswith("$") for key in value):
            return _variable(value, where)
        return [p for key, item in value.items() for p in _variables(item, f"{where}.{key}")]
    return []


def _leaves(value, prefix):
    if isinstance(value, dict) and value and not any(k.startswith("$") for k in value):
        for key, item in value.items():
            yield from _leaves(item, f"{prefix}.{key}")
    else:
        yield prefix


def _menu_problem(path_text, facts, inventory, submenu_ok, where):
    parts = tuple(part.strip() for part in path_text.split(ARROW))
    entry = facts["_menu"].get(parts)
    shown = f" {ARROW} ".join(parts)
    if entry is None:
        return f"{where}: {shown!r} is not a path of the built menu bar"
    if entry["submenu"]:
        return None if submenu_ok else f"{where}: {shown!r} is a submenu, not an item"
    if entry["selector"] not in inventory.get("selectors", {}):
        return (f"{where}: {shown!r}'s selector {entry['selector']!r} is not in "
                "inventory.json's selectors")
    return None


def _show_me(entry, facts, inventory, where):
    if not isinstance(entry, dict):
        return [f"{where} is not an object"]
    if "menu" in entry:
        if set(entry) != {"menu"} or not isinstance(entry["menu"], str):
            return [f"{where}: a menu Show Me is exactly {{\"menu\": \"A {ARROW} B\"}}"]
        problem = _menu_problem(entry["menu"], facts, inventory, False, where)
        return [problem] if problem else []
    if "tool" not in entry or not set(entry) <= {"tool", "args"}:
        return [f"{where}: a tool Show Me is {{tool, args?}}, not {sorted(entry)}"]
    tool, args = entry["tool"], entry.get("args", {})
    if tool in facts["dev_tools"]:
        return [f"{where}: {tool!r} is a dev tool, which Distribution does not have"]
    if tool not in facts["tools"]:
        return [f"{where}: unknown tool {tool!r}"]
    if not isinstance(args, dict):
        return [f"{where}: args is not an object"]
    properties = facts["tools"][tool]["properties"]
    out = []
    for key, value in args.items():
        if key not in properties:
            out.append(f"{where}: {tool} has no argument {key!r} "
                       f"(it takes {', '.join(sorted(properties)) or 'none'})")
            continue
        out += _variables(value, f"{where} {tool}.{key}")
        allowed = properties[key].get("enum") if isinstance(properties[key], dict) else None
        if allowed and isinstance(value, str) and not value.startswith("$") \
                and value not in allowed:
            out.append(f"{where}: {tool}.{key} {value!r} is not one of {allowed}")
    group = PATCH_GROUPS.get(tool)
    if group and isinstance(args.get("patch"), dict):
        for leaf in _leaves(args["patch"], group):
            if not _resolves(facts["clips"], leaf):
                out.append(f"{where}: {tool}'s patch path {leaf!r} is not in the fixture clips")
    return out


def _wait(wait, facts):
    if not isinstance(wait, dict) or not wait:
        return ["wait holds no condition"]
    out = []
    for key, value in wait.items():
        if key not in WAIT_KEYS:
            out.append(f"wait has an unknown condition {key!r}")
        elif key == "selection":
            out += _filter(value, "wait.selection", extra=("min", "max"))
            if isinstance(value, dict):
                low = value.get("min", 1)
                if not _int(low) or low < 0:
                    out.append("wait.selection.min is not an integer ≥ 0")
                elif "max" in value and (not _int(value["max"]) or value["max"] < low):
                    out.append("wait.selection.max is not an integer ≥ min")
        elif key == "changed":
            paths = [value] if isinstance(value, str) else value
            if not isinstance(paths, list) or not paths \
                    or not all(isinstance(p, str) for p in paths):
                out.append("wait.changed is not a path or a list of paths")
                continue
            out += [f"wait.changed path {p!r} is not in the fixture clips" for p in paths
                    if not _resolves(facts["clips"], p)]
        elif key == "clips":
            if not isinstance(value, dict) or not set(value) <= {"added", "kind"} \
                    or not _int(value.get("added")) or value["added"] < 1:
                out.append("wait.clips is {added: int ≥ 1, kind?}")
            elif "kind" in value and value["kind"] not in KINDS:
                out.append(f"wait.clips.kind {value['kind']!r} is not one of {', '.join(KINDS)}")
        elif key == "playhead":
            if not isinstance(value, dict) or set(value) != {"inside"} \
                    or value["inside"] not in REFS:
                out.append("wait.playhead is {inside: \"$selection\"|\"$created\"}")
        elif key == "range":
            if value not in ({"set": True}, {"changed": "start"}, {"changed": "end"}):
                out.append("wait.range is {set: true} or {changed: \"start\"|\"end\"}")
        elif key == "sheet":
            if value != "export":
                out.append(f"wait.sheet {value!r} is not \"export\"")
        elif value is not True:
            out.append(f"wait.{key} is not true")
    return out


def _reveal(reveal, targets):
    if not isinstance(reveal, dict) or "tab" not in reveal \
            or not set(reveal) <= {"tab", "sub_tab", "section"}:
        return ["reveal is {tab, sub_tab?, section?}"]
    tab, sub_tab = reveal["tab"], reveal.get("sub_tab")
    if tab not in targets["tabs"]:
        return [f"reveal.tab {tab!r} is not one of {targets['tabs']}"]
    if sub_tab is not None and (tab != "clip" or sub_tab not in targets["sub_tabs"]):
        return [f"reveal.sub_tab {sub_tab!r} is not a Clip tab sub-tab of {targets['sub_tabs']}"]
    if "section" in reveal:
        home = targets["sections"].get(reveal["section"])
        if home is None:
            return [f"reveal.section {reveal['section']!r} is not in the target table"]
        if (home["tab"], home["sub_tab"]) != (tab, sub_tab):
            return [f"reveal.section {reveal['section']!r} lives on {home['tab']}"
                    f"{'/' + home['sub_tab'] if home['sub_tab'] else ''}, not {tab}"
                    f"{'/' + sub_tab if sub_tab else ''}"]
    return []


def _spotlight(name, targets):
    if not isinstance(name, str):
        return ["spotlight is not a string"]
    if name in targets["fixed"]:
        return []
    if name.startswith("section:") and name[len("section:"):] in targets["sections"]:
        return []
    if name.startswith("clip:") and name[len("clip:"):] in targets["clip_refs"]:
        return []
    return [f"unknown spotlight {name!r}"]


def _sentence(text, facts, inventory):
    out = []
    if ARROW in BOLD.sub("", text):
        out.append(f"the sentence has a {ARROW} outside a bold span")
    for span in BOLD.findall(text):
        if ARROW in span:
            problem = _menu_problem(span, facts, inventory, True, "the sentence")
            if problem:
                out.append(problem)
    return out


def _step(step, facts, inventory):
    out = _sentence(step["text"], facts, inventory)
    targets = facts["targets"]
    for key, value in step.items():
        if key == "text":
            continue
        if key not in STEP_KEYS:
            out.append(f"unknown step key {key!r}")
        elif key == "reveal":
            out += _reveal(value, targets)
        elif key == "spotlight":
            out += _spotlight(value, targets)
        elif key == "wait":
            out += _wait(value, facts)
        elif key == "optional":
            if value is not True:
                out.append("optional is not true")
        elif key == "show_me":
            entries = value if isinstance(value, list) else [value]
            if not entries:
                out.append("show_me is an empty list")
            for index, entry in enumerate(entries):
                where = f"show_me[{index}]" if isinstance(value, list) else "show_me"
                out += _show_me(entry, facts, inventory, where)
    return out


def check(document: dict, facts: dict, inventory: dict, sources: Path) -> list:
    """Every vocabulary, catalog, table, menu and schema problem in `document`."""
    facts = dict(facts, _menu={tuple(e["path"]): e for e in facts["menu"]})
    problems = []
    for page in document["pages"]:
        for tutorial in page["tutorials"]:
            tid = tutorial["id"]

            def add(message, step=None, page=page["page"], tid=tid):
                problems.append(Problem(page, 0, tid, step, message))

            if not re.fullmatch(r"[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+", tid):
                add(f"the id {tid!r} is not dotted lowercase words")
            needs = tutorial["needs"]
            if not isinstance(needs, dict) or not set(needs) <= {"clip"}:
                add("needs is {clip: <filter>}")
            elif "clip" in needs:
                for message in _filter(needs["clip"], "needs.clip"):
                    add(message)
            for number, step in enumerate(tutorial["steps"], start=1):
                for message in _step(step, facts, inventory):
                    add(message, number)
    table = set(facts["targets"]["sections"])
    literals = set()
    for path in sorted(Path(sources).glob("*.swift")):
        literals |= set(LITERAL.findall(path.read_text(encoding="utf-8")))
    for missing in sorted(table - literals):
        problems.append(Problem(TABLE_PAGE, 0, None, None,
                                f"the table's section {missing!r} has no `id: \"{missing}\", "
                                "title:` literal in the sources"))
    for missing in sorted(literals - table):
        problems.append(Problem(TABLE_PAGE, 0, None, None,
                                f"the sources' section {missing!r} is not in the table"))
    return problems


# ---------------------------------------------------------------------------


def line(problem) -> str:
    where = problem.page
    if problem.tutorial is not None:
        where += f" tutorial {problem.tutorial}"
    if problem.step is not None:
        where += f" step {problem.step}"
    message = problem.message if not problem.line else f"line {problem.line}: {problem.message}"
    return f"FAIL {where}: {message}"


def run(guide, facts, inventory, sources):
    document, problems = parse_guide(guide)
    problems = problems + check(document, facts, inventory, sources)
    tutorials = sum(len(page["tutorials"]) for page in document["pages"])
    steps = sum(len(t["steps"]) for page in document["pages"] for t in page["tutorials"])
    return tutorials, steps, problems


def _replace(relative, before, after):
    def edit(folder):
        path = folder / relative
        text = path.read_text(encoding="utf-8")
        assert text.count(before) == 1, f"{relative}: {before!r} found {text.count(before)}×"
        path.write_text(text.replace(before, after), encoding="utf-8")
    return edit


def _copy_page(folder):
    shutil.copy(folder / "guide" / "model.md", folder / "guide" / "zz-copy.md")


M = "guide/model.md"
ID = "model.every_key"
# name: (edit of the copy, expected (page, tutorial, step))
MUTANTS = {
    "unknown-step-key": (_replace(M, '"optional": true}', '"optional": true, "blink": true}'),
                         ("model.md", ID, 13)),
    "unknown-tool": (_replace(M, '"tool": "split"', '"tool": "splat"'), ("model.md", ID, 4)),
    "unknown-arg": (_replace(M, '"clips": "$selection", "patch"', '"clipz": "$selection", '
                                                                   '"patch"'),
                    ("model.md", ID, 2)),
    "dev-tool": (_replace(M, '"tool": "set_selection"', '"tool": "snapshot_ui"'),
                 ("model.md", ID, 1)),
    "enum-value": (_replace(M, '"range": "in_out"', '"range": "inout"'), ("model.md", ID, 12)),
    "unknown-spotlight": (_replace(M, '"spotlight": "ruler"', '"spotlight": "rulers"'),
                          ("model.md", ID, 3)),
    "section-not-in-table": (_replace(M, '"section": "audio.volume"}',
                                      '"section": "audio.volumes"}'), ("model.md", ID, 2)),
    "section-other-home": (_replace(M, '"sub_tab": "text"', '"sub_tab": "sound"'),
                           ("model.md", ID, 6)),
    "sentence-menu-absent": (_replace(M, "**Mark ▸ Set In**", "**Mark ▸ Set Inn**"),
                             ("model.md", ID, 8)),
    "menu-not-in-inventory": (_replace(M, '{"menu": "File ▸ Export…"}',
                                       '{"menu": "Edit ▸ Fancy"}'), ("model.md", ID, 11)),
    "changed-absent": (_replace(M, '"changed": "transition_in"', '"changed": "transition_out"'),
                       ("model.md", ID, 7)),
    "unknown-variable": (_replace(M, '"$selection", "at": "$playhead"',
                                  '"$selection", "at": "$playhed"'), ("model.md", ID, 4)),
    "duplicate-id": (_copy_page, ("zz-copy.md", ID, None)),
    "table-source-mismatch": (_replace("sources/Sections.swift",
                                       'id: "doc.canvas", title: "Canvas",\n', ""),
                              (TABLE_PAGE, None, None)),
}


def _case(name, edit=None):
    folder = WORK / "selftest" / name
    shutil.rmtree(folder, ignore_errors=True)
    shutil.copytree(FIXTURES, folder)
    if edit:
        edit(folder)
    facts = json.loads((folder / "facts.json").read_text(encoding="utf-8"))
    inventory = json.loads((folder / "inventory.json").read_text(encoding="utf-8"))
    return run(folder / "guide", facts, inventory, folder / "sources")


def selftest() -> int:
    failures = 0
    tutorials, steps, problems = _case("control")
    ok = not problems and tutorials == 1
    failures += not ok
    print(f"{'PASS' if ok else 'FAIL'} CONTROL: {tutorials} tutorial, {steps} steps, "
          f"{len(problems)} problems" + "".join(f"\n    {line(p)}" for p in problems))
    for name, (edit, expected) in MUTANTS.items():
        try:
            _, _, problems = _case(name, edit)
        except AssertionError as error:
            failures += 1
            print(f"FAIL {name}: the mutant could not be made: {error}")
            continue
        got = [(p.page, p.tutorial, p.step) for p in problems]
        ok = got == [expected]
        failures += not ok
        print(f"{'PASS' if ok else 'FAIL'} {name}: "
              + ("; ".join(line(p) for p in problems) or "no problem"))
    total = len(MUTANTS) + 1
    print(f"tutorial_check --selftest: {total - failures}/{total} passed")
    return 0 if failures == 0 else 1


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--facts", type=Path, help="read the facts from FILE, no build")
    parser.add_argument("--save-facts", type=Path, help="write the probe's facts to FILE")
    parser.add_argument("--selftest", action="store_true")
    args = parser.parse_args(argv)
    if args.selftest:
        return selftest()
    try:
        facts = (json.loads(args.facts.read_text(encoding="utf-8")) if args.facts
                 else build_facts())
    except (ProbeFailed, OSError, ValueError) as error:
        print(f"FAIL probe: {error}")
        print("tutorial_check: the facts could not be read (a scored failure)")
        return 1
    if args.save_facts:
        args.save_facts.parent.mkdir(parents=True, exist_ok=True)
        args.save_facts.write_text(json.dumps(facts, indent=1, ensure_ascii=False) + "\n",
                                   encoding="utf-8")
    inventory = json.loads(INVENTORY.read_text(encoding="utf-8"))
    tutorials, steps, problems = run(GUIDE, facts, inventory, SOURCES)
    for problem in problems:
        print(line(problem))
    print(f"tutorial_check: {tutorials} tutorials, {steps} steps, {len(problems)} problems")
    return 0 if not problems else 1


if __name__ == "__main__":
    sys.exit(main())

// Tutorials TU1 — the app's facts `tutorial_check.py` checks the guide's
// tutorials against (spec §11 TU-2): the prepared catalog, the dev tools'
// names, the spotlight target table, the built menu bar and a fixture
// project's clips as the core writes them.
//
// Compiled AS `main.swift` over every file in `app/Sources` but the app's own
// `main.swift`, with `-D FRAMEJOB_DEV_TOOLS`, through `swift_build.py`'s
// `build()` by `tutorial_check.py`.
//
//   tutorial_probe <work-dir>
//
// Prints exactly one stdout line:
//   ANSWER {"tools": {name: {"properties": {…}}}, "dev_tools": [sorted],
//           "targets": TutorialTargets.manifest(),
//           "menu": [{"path": [titles], "selector": str|null, "submenu": bool}],
//           "clips": [the fixture's clips, as the core writes them]}
//   or ANSWER {"error": "…"} when a fact could not be read.
//
// Nothing binds the agent socket, opens a window or reads media: the fixture's
// media clip is a stand-in `add_media` descriptor with no file behind it.
import AppKit

final class ProbeDocumentController: NSDocumentController {
    override var defaultType: String? { ProjectDocument.projectTypeIdentifier }
}
_ = ProbeDocumentController()

let app = NSApplication.shared
app.setActivationPolicy(.prohibited)
let delegate = AppDelegate()
delegate.applicationWillFinishLaunching(
    Notification(name: NSApplication.willFinishLaunchingNotification, object: app))
AgentLane.prepareAtLaunch()

func answer(_ body: [String: Any]) -> Never {
    let data = (try? JSONSerialization.data(withJSONObject: body, options: [.sortedKeys]))
        ?? Data("{\"error\":\"the answer did not encode\"}".utf8)
    print("ANSWER " + (String(data: data, encoding: .utf8) ?? "{}"))
    fflush(stdout)
    exit(0)
}

func fail(_ reason: String) -> Never { answer(["error": reason]) }

// MARK: - The catalog

guard let catalog = AgentServer.shared.preparedCatalog,
      let tools = (try? JSONSerialization.jsonObject(with: Data(catalog.utf8))) as? [[String: Any]]
else { fail("no prepared catalog") }
var toolFacts: [String: Any] = [:]
for tool in tools {
    guard let name = tool["name"] as? String else { continue }
    let schema = tool["inputSchema"] as? [String: Any] ?? [:]
    toolFacts[name] = ["properties": schema["properties"] as? [String: Any] ?? [:]]
}

// MARK: - The menu bar, as `probe_sheets.swift`'s `runMenu` walks it

var menu: [[String: Any]] = []
func walk(_ items: NSMenu, _ path: [String]) {
    for item in items.items where !item.isSeparatorItem {
        let here = path + [item.title]
        menu.append([
            "path": here,
            "selector": item.action.map { NSStringFromSelector($0) as Any } ?? NSNull(),
            "submenu": item.submenu != nil,
        ])
        if let sub = item.submenu { walk(sub, here) }
    }
}
guard let mainMenu = NSApp.mainMenu else { fail("no main menu after willFinishLaunching") }
walk(mainMenu, [])

